package media

import (
	"context"
	"errors"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Sentinel errors for storage.
var (
	// ErrStorageKeyUnsafe means a storage key tried to escape the storage root.
	ErrStorageKeyUnsafe = errors.New("media: unsafe storage key")
	// ErrStorageObjectMissing means the object was never written or already deleted.
	ErrStorageObjectMissing = errors.New("media: stored object not found")
)

// Storage stores uploaded objects.
//
// Keys are generated by the server, never by the client, so an implementation only
// has to defend against a bug in key generation rather than against a user.
type Storage interface {
	// Put stores size bytes from reader under key.
	Put(ctx context.Context, key string, reader io.Reader, size int64) error
	// ReadHead returns up to n leading bytes of the object.
	ReadHead(ctx context.Context, key string, n int) ([]byte, error)
	// Open returns the object for streaming. The caller owns the reader.
	Open(ctx context.Context, key string) (io.ReadCloser, error)
	// Delete removes the object. Deleting a missing object is not an error.
	Delete(ctx context.Context, key string) error
}

// HeadSampleSize is how many leading bytes inspection receives.
//
// The security service checks the complete magic number of every accepted type (the
// longest is 12 bytes for WebP) and additionally scans the sample for HTML/SVG polyglot
// markers, so it gets more than a bare signature: 512 bytes is enough for the marker
// scan while keeping the read cheap. The sample is never the whole file.
const HeadSampleSize = 512

// LocalStorage stores objects under a directory on the local filesystem.
type LocalStorage struct {
	root string
}

var _ Storage = (*LocalStorage)(nil)

// NewLocalStorage prepares a storage root.
func NewLocalStorage(root string) (*LocalStorage, error) {
	if strings.TrimSpace(root) == "" {
		return nil, errors.New("media: storage root is required")
	}
	absolute, err := filepath.Abs(root)
	if err != nil {
		return nil, err
	}
	if err := os.MkdirAll(absolute, 0o755); err != nil {
		return nil, err
	}
	return &LocalStorage{root: absolute}, nil
}

// Root returns the absolute storage root.
func (s *LocalStorage) Root() string { return s.root }

// Put stores the object, creating its shard directory.
func (s *LocalStorage) Put(ctx context.Context, key string, reader io.Reader, size int64) error {
	if err := ctx.Err(); err != nil {
		return err
	}

	path, err := s.resolve(key)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}

	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	defer file.Close()

	// CopyN bounds the write to the declared size, so a client cannot stream more
	// bytes than the session promised.
	written, err := io.CopyN(file, reader, size)
	if err != nil {
		return err
	}
	if written != size {
		return errors.New("media: stored fewer bytes than declared")
	}
	return file.Sync()
}

// ReadHead returns up to n leading bytes of the object.
func (s *LocalStorage) ReadHead(ctx context.Context, key string, n int) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if n <= 0 || n > HeadSampleSize {
		n = HeadSampleSize
	}

	path, err := s.resolve(key)
	if err != nil {
		return nil, err
	}

	file, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, ErrStorageObjectMissing
		}
		return nil, err
	}
	defer file.Close()

	buffer := make([]byte, n)
	read, err := io.ReadFull(file, buffer)
	if err != nil && !errors.Is(err, io.EOF) && !errors.Is(err, io.ErrUnexpectedEOF) {
		return nil, err
	}
	return buffer[:read], nil
}

// Open returns the stored object for streaming.
func (s *LocalStorage) Open(ctx context.Context, key string) (io.ReadCloser, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	path, err := s.resolve(key)
	if err != nil {
		return nil, err
	}

	file, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, ErrStorageObjectMissing
		}
		return nil, err
	}
	return file, nil
}

// Delete removes the object.
func (s *LocalStorage) Delete(ctx context.Context, key string) error {
	if err := ctx.Err(); err != nil {
		return err
	}

	path, err := s.resolve(key)
	if err != nil {
		return err
	}
	if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
		return err
	}
	return nil
}

// List returns every stored object key, relative to the root and slash separated.
//
// The garbage collector needs to see objects no row refers to, which is the only way to
// find files left behind by a crash between an upload and its database row. Keys are
// sorted so a dry-run report is deterministic.
func (s *LocalStorage) List(ctx context.Context) ([]string, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	keys := make([]string, 0)
	err := filepath.WalkDir(s.root, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if err := ctx.Err(); err != nil {
			return err
		}
		if entry.IsDir() {
			return nil
		}
		relative, err := filepath.Rel(s.root, path)
		if err != nil {
			return err
		}
		keys = append(keys, filepath.ToSlash(relative))
		return nil
	})
	if err != nil {
		return nil, err
	}
	sort.Strings(keys)
	return keys, nil
}

// resolve maps a key to a path inside the root.
//
// The containment check runs on the cleaned absolute path, so an implementation bug
// that produced "../" still cannot escape: the operation fails instead.
func (s *LocalStorage) resolve(key string) (string, error) {
	if key == "" || strings.ContainsRune(key, 0) {
		return "", ErrStorageKeyUnsafe
	}
	// Both separators are refused, and a leading slash counts as absolute on every
	// platform even though Windows does not treat "/x" as rooted.
	if strings.Contains(key, "\\") || strings.HasPrefix(key, "/") || filepath.IsAbs(key) {
		return "", ErrStorageKeyUnsafe
	}

	cleaned := filepath.Clean(filepath.FromSlash(key))
	if cleaned == "." || strings.HasPrefix(cleaned, "..") {
		return "", ErrStorageKeyUnsafe
	}

	path := filepath.Join(s.root, cleaned)
	relative, err := filepath.Rel(s.root, path)
	if err != nil || strings.HasPrefix(relative, "..") {
		return "", ErrStorageKeyUnsafe
	}
	return path, nil
}
